-- ==============================================================================
-- VROOMVALUE - MASTER DATABASE SCHEMA & SEED DATA (ALL-IN-ONE)
-- ==============================================================================
-- INSTRUCTIONS FOR SETUP:
-- 1. Create your new project in Supabase: https://supabase.com/dashboard
-- 2. Open the SQL Editor (from the left sidebar, click the SQL icon)
-- 3. Click 'New query'
-- 4. Select all text in this file (Ctrl + A), copy (Ctrl + C), and paste into the editor
-- 5. Click 'Run' (or press Ctrl + Enter)
-- 6. Done! All tables, security policies, triggers, and all 50 vehicles will be ready.
-- ==============================================================================

-- 1. EXTENSIONS
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. USERS TABLE
CREATE TABLE IF NOT EXISTS public.users (
    id TEXT PRIMARY KEY,
    email TEXT,
    name TEXT,
    role TEXT DEFAULT 'user',
    phone TEXT,
    dob TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. CARS TABLE (Complete Inventory)
CREATE TABLE IF NOT EXISTS public.cars (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    make TEXT NOT NULL,
    model TEXT NOT NULL,
    variant TEXT,
    year INT NOT NULL,
    priceinr BIGINT NOT NULL DEFAULT 0,
    kms INT NOT NULL DEFAULT 0,
    fuel TEXT,
    transmission TEXT,
    bodytype TEXT,
    city TEXT,
    sellertype TEXT DEFAULT 'VroomValue Certified',
    owner TEXT DEFAULT '1st Owner',
    certified BOOLEAN DEFAULT TRUE,
    status TEXT DEFAULT 'approved',
    enginecapacity INT,
    mileagekmpl FLOAT,
    seats INT DEFAULT 5,
    color TEXT,
    rto TEXT,
    insurancevalidity TEXT,
    accidental BOOLEAN DEFAULT FALSE,
    servicehistory BOOLEAN DEFAULT TRUE,
    description TEXT,
    images JSONB DEFAULT '[]'::jsonb,
    features JSONB DEFAULT '[]'::jsonb,
    safetyfeatures JSONB DEFAULT '[]'::jsonb,
    buyer_details JSONB,
    reserve_details JSONB,
    valuation JSONB,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. SELL REQUESTS TABLE (Customer listings awaiting approval)
CREATE TABLE IF NOT EXISTS public.sell_requests (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    make TEXT NOT NULL,
    model TEXT NOT NULL,
    variant TEXT,
    year INT NOT NULL,
    priceinr BIGINT DEFAULT 0,
    kms INT DEFAULT 0,
    fuel TEXT,
    transmission TEXT,
    bodytype TEXT,
    city TEXT,
    owner INT DEFAULT 1,
    status TEXT DEFAULT 'pending',
    name TEXT,
    email TEXT,
    phone TEXT,
    rtonumber TEXT,
    location TEXT,
    description TEXT,
    requestdate TIMESTAMPTZ DEFAULT NOW(),
    requestedat TIMESTAMPTZ DEFAULT NOW(),
    images JSONB DEFAULT '[]'::jsonb,
    features JSONB DEFAULT '[]'::jsonb,
    safetyfeatures JSONB DEFAULT '[]'::jsonb,
    valuation JSONB,
    enginecapacity INT,
    mileagekmpl FLOAT,
    seats INT DEFAULT 5,
    color TEXT,
    rto TEXT,
    insurancevalidity TEXT,
    accidental BOOLEAN DEFAULT FALSE,
    servicehistory BOOLEAN DEFAULT TRUE,
    sellertype TEXT DEFAULT 'Individual',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. TEST DRIVES TABLE (Customer booking inquiries)
CREATE TABLE IF NOT EXISTS public.test_drives (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    carid BIGINT,
    userid TEXT,
    cartitle TEXT,
    customername TEXT,
    customerphone TEXT,
    name TEXT,
    phone TEXT,
    date TEXT,
    time TEXT,
    status TEXT DEFAULT 'pending',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. PERMISSIONS & ROLE GRANTS (Eliminates 406 Not Acceptable / 401 Unauthorized errors)
GRANT USAGE ON SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON ALL ROUTINES IN SCHEMA public TO postgres, anon, authenticated, service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO postgres, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO postgres, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON ROUTINES TO postgres, anon, authenticated, service_role;

-- 7. ROW LEVEL SECURITY (RLS) POLICIES
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cars ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sell_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.test_drives ENABLE ROW LEVEL SECURITY;

-- CARS: Public read for browsing, authenticated/service role full access
DROP POLICY IF EXISTS "Public Read Cars" ON public.cars;
CREATE POLICY "Public Read Cars" ON public.cars FOR SELECT USING (true);

DROP POLICY IF EXISTS "Full Manage Cars" ON public.cars;
CREATE POLICY "Full Manage Cars" ON public.cars FOR ALL USING (true) WITH CHECK (true);

-- USERS: Profile management
DROP POLICY IF EXISTS "Public Read Users" ON public.users;
CREATE POLICY "Public Read Users" ON public.users FOR SELECT USING (true);

DROP POLICY IF EXISTS "User Self Insert" ON public.users;
CREATE POLICY "User Self Insert" ON public.users FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "User Self Update" ON public.users;
CREATE POLICY "User Self Update" ON public.users FOR UPDATE USING (true) WITH CHECK (true);

-- SELL REQUESTS: Anyone can submit a car to sell, admins/users can read/manage
DROP POLICY IF EXISTS "Public Submit Sell Request" ON public.sell_requests;
CREATE POLICY "Public Submit Sell Request" ON public.sell_requests FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Read Sell Requests" ON public.sell_requests;
CREATE POLICY "Read Sell Requests" ON public.sell_requests FOR SELECT USING (true);

DROP POLICY IF EXISTS "Manage Sell Requests" ON public.sell_requests;
CREATE POLICY "Manage Sell Requests" ON public.sell_requests FOR ALL USING (true) WITH CHECK (true);

-- TEST DRIVES: Anyone can request, admins can view/manage
DROP POLICY IF EXISTS "Public Request Test Drive" ON public.test_drives;
CREATE POLICY "Public Request Test Drive" ON public.test_drives FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "View Test Drives" ON public.test_drives;
CREATE POLICY "View Test Drives" ON public.test_drives FOR SELECT USING (true);

DROP POLICY IF EXISTS "Manage Test Drives" ON public.test_drives;
CREATE POLICY "Manage Test Drives" ON public.test_drives FOR ALL USING (true) WITH CHECK (true);

-- 8. AUTH SYNC TRIGGER
-- Automatically creates a matching profile in public.users whenever a user registers in Supabase Auth
CREATE OR REPLACE FUNCTION public.handle_new_user() 
RETURNS trigger AS $$
BEGIN
  INSERT INTO public.users (id, email, name, role, phone, dob)
  VALUES (
    new.id::text, 
    new.email, 
    COALESCE(new.raw_user_meta_data->>'name', 'User'), 
    CASE WHEN new.email = 'admin@vroomvalue.in' THEN 'admin' ELSE 'user' END, 
    COALESCE(new.raw_user_meta_data->>'phone', ''),
    COALESCE(new.raw_user_meta_data->>'dob', NULL)
  )
  ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email,
    name = COALESCE(EXCLUDED.name, public.users.name);
  
  RETURN new;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Failed to create user profile for %: %', new.email, SQLERRM;
    RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- 9. ADMIN SECURITY TRIGGER
-- Enforces admin role for admin@vroomvalue.in
CREATE OR REPLACE FUNCTION public.check_admin_email()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.email = 'admin@vroomvalue.in' THEN
    NEW.role := 'admin';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

DROP TRIGGER IF EXISTS enforce_admin_email ON public.users;
CREATE TRIGGER enforce_admin_email
  BEFORE INSERT OR UPDATE ON public.users
  FOR EACH ROW
  EXECUTE FUNCTION public.check_admin_email();

-- 10. PRE-SEED DEFAULT ADMIN USER
INSERT INTO public.users (id, email, name, role)
VALUES ('00000000-0000-0000-0000-000000000001', 'admin@vroomvalue.in', 'Admin', 'admin')
ON CONFLICT (id) DO UPDATE SET role = 'admin', name = 'Admin';

